* { box-sizing: border-box; }
:root { color-scheme: light; font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; font-size: 16px; color: #28243a; background: #eee9df; }
body { min-width: 360px; min-height: 100vh; margin: 0; padding: 36px 18px; display: grid; place-items: center; background-color: #eee9df; background-image: radial-gradient(#d8d0c2 1px, transparent 1px); background-size: 18px 18px; }
button, textarea { font: inherit; }
button { cursor: pointer; }
.board { width: min(780px, 100%); padding: clamp(22px, 5vw, 42px); background: #fffdf8; border: 2px solid #28243a; box-shadow: 8px 8px 0 #28243a; }
.board-header { display: flex; justify-content: space-between; align-items: flex-start; gap: 16px; margin-bottom: 28px; }
.eyebrow { margin: 0 0 8px; color: #706a81; font-size: .8rem; font-weight: 800; letter-spacing: .12em; }
h1 { margin: 0; font-size: clamp(1.8rem, 6vw, 2.5rem); line-height: 1.1; letter-spacing: -.04em; }
h1 span { color: #ef9c66; }
.subtitle { margin: 8px 0 0; color: #625d70; }
.counter { flex: none; margin: 4px 0 0; padding: 9px 12px; background: #e6e0f2; border: 2px solid #28243a; font-size: .9rem; }
.counter strong { font-size: 1.1rem; }
.composer { padding: 18px; background: #f6f2ea; border: 2px solid #28243a; }
.composer > label, .color-picker legend { display: block; margin-bottom: 9px; font-weight: 750; }
textarea { width: 100%; min-height: 88px; resize: vertical; padding: 12px; border: 2px solid #c9c2b6; border-radius: 0; background: #fffdf8; color: #28243a; }
textarea:focus, button:focus-visible, input:focus-visible + span, [contenteditable="true"]:focus { outline: 3px solid #7762b3; outline-offset: 3px; }
.form-footer { display: flex; align-items: end; justify-content: space-between; gap: 16px; margin-top: 14px; }
.color-picker { display: flex; align-items: center; gap: 10px; min-width: 0; margin: 0; padding: 0; border: 0; }
.color-picker legend { float: left; margin: 0 4px 0 0; font-size: .9rem; }
.swatch { position: relative; display: inline-flex; width: 27px; height: 27px; cursor: pointer; }
.swatch input { position: absolute; width: 1px; height: 1px; opacity: 0; }
.swatch span { width: 24px; height: 24px; border: 2px solid #28243a; }
.swatch input:checked + span { outline: 2px solid #28243a; outline-offset: 2px; }
.swatch-lemon span, .note-lemon { background: #f5df75; }
.swatch-rose span, .note-rose { background: #f4b6b0; }
.swatch-mint span, .note-mint { background: #a9d9c0; }
.swatch-lilac span, .note-lilac { background: #c8b8e8; }
.add-button, .danger-button { padding: 10px 15px; color: #fffdf8; background: #39334f; border: 2px solid #28243a; font-weight: 750; }
.add-button:hover, .danger-button:hover { background: #554b72; }
.add-button:active, .danger-button:active, .secondary-button:active, .clear-button:active { transform: translateY(2px); }
.notes-section { margin-top: 32px; }
.section-heading { display: flex; justify-content: space-between; align-items: center; gap: 12px; border-bottom: 2px solid #28243a; }
h2 { margin: 0 0 10px; font-size: 1.25rem; }
.clear-button { margin-bottom: 8px; padding: 7px 10px; color: #4d465f; background: transparent; border: 1px solid #9a93a6; font-weight: 650; }
.clear-button:hover { background: #eee9f4; }
.empty-state { padding: 28px 12px; color: #706a81; text-align: center; }
.notes-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(min(190px, 100%), 1fr)); gap: 16px; padding-top: 18px; }
.note { min-height: 155px; padding: 15px; border: 2px solid #28243a; box-shadow: 4px 4px 0 #28243a; transform: rotate(-1deg); }
.note:nth-child(even) { transform: rotate(1deg); }
.note-text { min-height: 90px; white-space: pre-wrap; overflow-wrap: anywhere; line-height: 1.5; }
.note-text[contenteditable="true"] { cursor: text; }
.note-actions { display: flex; justify-content: flex-end; margin-top: 12px; }
.delete-button { padding: 6px 9px; color: #39334f; background: rgba(255,255,255,.55); border: 1px solid #39334f; font-weight: 650; }
.delete-button:hover { background: #fffdf8; }
footer { margin-top: 30px; color: #706a81; font-size: .9rem; text-align: center; }
dialog { width: min(420px, calc(100% - 32px)); padding: 0; border: 2px solid #28243a; box-shadow: 7px 7px 0 #28243a; color: #28243a; }
dialog::backdrop { background: rgba(40, 36, 58, .48); }
.dialog-card { padding: 24px; }
.dialog-card p { color: #625d70; }
.dialog-actions { display: flex; justify-content: flex-end; gap: 10px; margin-top: 22px; }
.secondary-button, .danger-button { padding: 9px 12px; border: 2px solid #28243a; font-weight: 700; }
.secondary-button { color: #28243a; background: #fffdf8; }
[hidden] { display: none !important; }
@media (max-width: 480px) { body { padding: 18px 12px; } .board-header { flex-direction: column; } .form-footer { align-items: stretch; flex-direction: column; } .add-button { width: 100%; } .color-picker { flex-wrap: wrap; } }

const form = document.querySelector('#note-form');
const input = document.querySelector('#note-text');
const grid = document.querySelector('#notes-grid');
const count = document.querySelector('#note-count');
const countLabel = document.querySelector('#count-label');
const emptyState = document.querySelector('#empty-state');
const clearButton = document.querySelector('#clear-all');
const dialog = document.querySelector('#clear-dialog');
const confirmClear = document.querySelector('#confirm-clear');

function updateBoard() {
  const total = grid.children.length;
  count.textContent = total;
  countLabel.textContent = total === 1 ? 'note' : 'notes';
  emptyState.hidden = total !== 0;
  clearButton.disabled = total === 0;
}

function addNote(text, color) {
  const card = document.createElement('article');
  card.className = `note note-${color}`;
  const noteText = document.createElement('div');
  noteText.className = 'note-text';
  noteText.contentEditable = 'true';
  noteText.setAttribute('role', 'textbox');
  noteText.setAttribute('aria-label', 'Edit note text');
  noteText.setAttribute('aria-multiline', 'true');
  noteText.textContent = text;
  const actions = document.createElement('div');
  actions.className = 'note-actions';
  const remove = document.createElement('button');
  remove.type = 'button';
  remove.className = 'delete-button';
  remove.textContent = 'Delete';
  remove.setAttribute('aria-label', 'Delete note');
  remove.addEventListener('click', () => { card.remove(); updateBoard(); });
  actions.append(remove);
  card.append(noteText, actions);
  grid.prepend(card);
  updateBoard();
}

form.addEventListener('submit', (event) => {
  event.preventDefault();
  const text = input.value.trim();
  if (!text) { input.focus(); return; }
  const color = form.querySelector('input[name="color"]:checked').value;
  addNote(text, color);
  input.value = '';
  input.focus();
});

clearButton.addEventListener('click', () => {
  if (grid.children.length) dialog.showModal();
});

confirmClear.addEventListener('click', (event) => {
  if (event.currentTarget.value === 'clear') {
    grid.replaceChildren();
    updateBoard();
  }
});

updateBoard();
